import { hasAnsi, parseAnsi, type AnsiSpan, type AnsiStyle } from "@/lib/ansi"

/** How serious a line is. Any other string is kept and shown as is; `error` and `fatal` count as errors. */
type LogLevel = "trace" | "debug" | "info" | "warn" | "error" | "fatal"

type LogLine = {
  /** Its place in the stream, from 1, never reused: lines keep their id when older ones leave the buffer. */
  id: number
  /** Which process or service wrote it, like `frontend`, `backend` or `db`. */
  source?: string
  level?: LogLevel | (string & {})
  /** When it was written, in ms since the epoch. */
  time?: number
  /** The text without escape sequences or control characters: what copy, search and agents read. */
  text: string
  /** Its styled runs, when it had SGR codes. */
  spans?: readonly AnsiSpan[]
}

/** A line to add: its raw text, which may hold ANSI escape codes, or the text with where it came from. */
type LogInput = string | { text: string; source?: string; level?: LogLine["level"]; time?: number | Date }

// Workaround: TypeScript's `Array.isArray` doesn't narrow a readonly array out of a union.
const isInputList = (input: LogInput | readonly LogInput[]): input is readonly LogInput[] => Array.isArray(input)

type LogWriteOptions = { source?: string; level?: LogLine["level"]; time?: number | Date }

type LogStoreSnapshot = {
  /** Changes on every notification, so it works as `useSyncExternalStore`'s snapshot. */
  version: number
  /** Changes when `clear()` empties the buffer. */
  generation: number
  /** The id of the oldest line in the buffer; `lastId + 1` while it's empty. */
  firstId: number
  /** The id of the newest line, 0 before any. */
  lastId: number
  size: number
  /** How many lines have left the buffer to keep it at `maxLines`, since the last `clear()`. */
  dropped: number
}

type LogStoreOptions = {
  /** The most lines kept; older ones leave as new ones arrive. @defaultValue 10000 */
  maxLines?: number
  /** Longer lines are cut to this many characters and end with "…". @defaultValue 10000 */
  maxLineLength?: number
  /**
   * Schedules a notification. By default one per animation frame, or one every few frames while listeners take
   * longer than half a frame. For tests and workers.
   */
  schedule?: (notify: () => void) => void
  /** The clock for lines without a time. Lines carry no time unless this or their input gives one. */
  now?: () => number
}

type LogStore = {
  /** Adds whole lines. Text with newlines becomes several lines. Listeners hear about it once per frame. */
  append: (input: LogInput | readonly LogInput[]) => void
  /**
   * Adds a chunk of a process's output as it arrives: whole lines are added, a partial last line waits for the
   * rest, and colours carry from one line to the next, per source, as in a terminal.
   */
  write: (chunk: string, options?: LogWriteOptions) => void
  /** Adds the partial line `write` holds for a source, like when its process exits. */
  end: (source?: string) => void
  /** Empties the buffer. */
  clear: () => void
  /** The line with this id, while it's in the buffer. */
  get: (id: number) => LogLine | undefined
  /** The lines in the buffer, oldest first, as a new array. */
  lines: () => LogLine[]
  getSnapshot: () => LogStoreSnapshot
  /** Called at most once per frame after lines arrive, and at once after `clear()`. */
  subscribe: (listener: () => void) => () => void
  /** Notifies now, with what arrived since the last notification. */
  flush: () => void
  readonly maxLines: number
}

type Pending = { text: string; style: AnsiStyle }

// Perf: slow listeners skip frames between notifications, so a flood of lines leaves scrolling and typing responsive.
const BUSY_FRAME_MS = 8
const MAX_SKIPPED_FRAMES = 3

function frames() {
  let skip = 0
  return {
    schedule(notify: () => void) {
      if (typeof requestAnimationFrame !== "function") {
        setTimeout(notify, 16 * (skip + 1))
        return
      }
      let left = skip
      const tick = () => {
        if (left-- > 0) requestAnimationFrame(tick)
        else notify()
      }
      requestAnimationFrame(tick)
    },
    took(ms: number) {
      skip = Math.min(MAX_SKIPPED_FRAMES, Math.floor(ms / BUSY_FRAME_MS))
    },
  }
}

const timeOf = (time: number | Date | undefined) => (time instanceof Date ? time.getTime() : time)

/**
 * A bounded buffer of log lines for `LogViewer`, fed from anywhere: a WebSocket, an EventSource, a child process's
 * output. Appending is cheap (no React work): the viewer reads what changed once per frame. Create it once, outside
 * render, and keep it for as long as the stream lives.
 */
function createLogStore(options: LogStoreOptions = {}): LogStore {
  const maxLines = Math.max(1, Math.floor(options.maxLines ?? 10_000))
  const maxLineLength = Math.max(1, Math.floor(options.maxLineLength ?? 10_000))
  const pace = frames()
  const schedule = options.schedule ?? pace.schedule
  const listeners = new Set<() => void>()
  // Perf: dropping old lines moves `head`; cutting the array once `head` passes `maxLines` copies each line at
  // most once more.
  let buffer: LogLine[] = []
  let head = 0
  let nextId = 1
  let generation = 0
  let dropped = 0
  let version = 0
  let scheduled = false
  let snapshot: LogStoreSnapshot = { version, generation, firstId: 1, lastId: 0, size: 0, dropped: 0 }
  const pending = new Map<string, Pending>()
  const carried = new Map<string, AnsiStyle>()

  const firstId = () => (head < buffer.length ? buffer[head]!.id : nextId)

  const notify = () => {
    scheduled = false
    version += 1
    snapshot = {
      version,
      generation,
      firstId: firstId(),
      lastId: nextId - 1,
      size: buffer.length - head,
      dropped,
    }
    const started = performance.now()
    for (const listener of listeners) listener()
    const recordTimeIncludingReactRender = () => pace.took(performance.now() - started)
    queueMicrotask(recordTimeIncludingReactRender)
  }

  const request = () => {
    if (scheduled) return
    scheduled = true
    schedule(() => {
      if (scheduled) notify()
    })
  }

  const push = (raw: string, meta: LogWriteOptions, style?: AnsiStyle) => {
    const cut = raw.length > maxLineLength ? `${raw.slice(0, maxLineLength)}…` : raw
    let text = cut
    let spans: readonly AnsiSpan[] | undefined
    let end = style
    if ((style && Object.keys(style).length > 0) || hasAnsi(cut)) {
      const parsed = parseAnsi(cut, style)
      text = parsed.text
      spans = parsed.spans
      end = parsed.style
    }
    const time = timeOf(meta.time) ?? options.now?.()
    const line: LogLine = { id: nextId, text }
    if (meta.source !== undefined) line.source = meta.source
    if (meta.level !== undefined) line.level = meta.level
    if (time !== undefined) line.time = time
    if (spans) line.spans = spans
    nextId += 1
    buffer.push(line)
    if (buffer.length - head > maxLines) {
      head += 1
      dropped += 1
      if (head >= maxLines) {
        buffer = buffer.slice(head)
        head = 0
      }
    }
    return end
  }

  const appendOne = (input: LogInput) => {
    const meta = typeof input === "string" ? {} : input
    const text = typeof input === "string" ? input : input.text
    if (!text.includes("\n")) {
      push(text, meta)
      return
    }
    for (const part of text.split("\n")) push(part, meta)
  }

  return {
    maxLines,
    append(input) {
      if (isInputList(input)) for (const item of input) appendOne(item)
      else appendOne(input)
      request()
    },
    write(chunk, meta = {}) {
      const key = meta.source ?? ""
      const held = pending.get(key)
      const parts = chunk.split("\n")
      const last = parts.pop() ?? ""
      let style = held?.style ?? carried.get(key) ?? {}
      if (parts.length === 0) {
        pending.set(key, { text: (held?.text ?? "") + last, style })
        return
      }
      parts[0] = (held?.text ?? "") + (parts[0] ?? "")
      for (const part of parts) style = push(part, meta, style) ?? {}
      carried.set(key, style)
      if (last === "") pending.delete(key)
      else pending.set(key, { text: last, style })
      request()
    },
    end(source) {
      const key = source ?? ""
      const held = pending.get(key)
      pending.delete(key)
      carried.delete(key)
      if (!held) return
      push(held.text, { source }, held.style)
      request()
    },
    clear() {
      buffer = []
      head = 0
      dropped = 0
      generation += 1
      pending.clear()
      carried.clear()
      notify()
    },
    get(id) {
      const index = head + id - firstId()
      return index >= head && index < buffer.length ? buffer[index] : undefined
    },
    lines: () => buffer.slice(head),
    getSnapshot: () => snapshot,
    subscribe(listener) {
      listeners.add(listener)
      return () => {
        listeners.delete(listener)
      }
    },
    flush() {
      if (scheduled) notify()
    },
  }
}

const errorLevels = new Set(["error", "fatal"])

/** Whether a line's level marks it as an error. */
function isErrorLevel(line: LogLine) {
  return line.level !== undefined && errorLevels.has(line.level.toLowerCase())
}

export { createLogStore, isErrorLevel }
export type { LogInput, LogLevel, LogLine, LogStore, LogStoreOptions, LogStoreSnapshot, LogWriteOptions }

import type { LogLine, LogStore } from "@/components/ui/log-viewer-store"

/** Which lines show: sources left out, and text every shown line contains (any case). */
type LogFilter = { hidden: ReadonlySet<string>; query: string }

/** What a sync changed: lines that now show at the end, and shown lines that left the buffer from the start. */
type LogIndexChange = { added: number; removed: number; rebuilt: boolean }

const compactAfterDropped = 1024

// Perf: ids are read from `start`, so dropping the oldest moves a number instead of copying the array.
function createSortedIdList() {
  let ids: number[] = []
  let start = 0
  const lowerBound = (id: number) => {
    let low = start
    let high = ids.length
    while (low < high) {
      const mid = (low + high) >>> 1
      if (ids[mid]! < id) low = mid + 1
      else high = mid
    }
    return low
  }
  return {
    get length() {
      return ids.length - start
    },
    at: (index: number) => (index < 0 || start + index >= ids.length ? undefined : ids[start + index]),
    push: (id: number) => void ids.push(id),
    dropBelow(id: number) {
      const from = start
      while (start < ids.length && ids[start]! < id) start++
      if (start > compactAfterDropped && start * 2 > ids.length) {
        ids = ids.slice(start)
        start = 0
      }
      return start - from
    },
    lowerBound: (id: number) => lowerBound(id) - start,
    indexOf(id: number) {
      const index = lowerBound(id)
      return ids[index] === id ? index - start : -1
    },
    clear() {
      ids = []
      start = 0
    },
  }
}

/**
 * The lines a `LogViewer` shows, as ids into its store, kept up to date as lines arrive and leave: each sync
 * reads only the new lines, and only a filter change reads the whole buffer again.
 */
function createLogIndex(isError: (line: LogLine) => boolean) {
  const shown = createSortedIdList()
  const errors = createSortedIdList()
  const sources: string[] = []
  const known = new Set<string>()
  let synced = 0
  let generation = -1
  let filter: LogFilter = { hidden: new Set(), query: "" }
  let needle = ""

  const matches = (line: LogLine) =>
    (line.source === undefined || !filter.hidden.has(line.source)) &&
    (needle === "" || line.text.toLowerCase().includes(needle))

  const take = (line: LogLine) => {
    if (line.source !== undefined && !known.has(line.source)) {
      known.add(line.source)
      sources.push(line.source)
    }
    if (!matches(line)) return false
    shown.push(line.id)
    if (isError(line)) errors.push(line.id)
    return true
  }

  function rebuild(store: LogStore): LogIndexChange {
    shown.clear()
    errors.clear()
    const snapshot = store.getSnapshot()
    let added = 0
    for (let id = snapshot.firstId; id <= snapshot.lastId; id++) {
      const line = store.get(id)
      if (line && take(line)) added++
    }
    synced = snapshot.lastId
    generation = snapshot.generation
    return { added, removed: 0, rebuilt: true }
  }

  return {
    get count() {
      return shown.length
    },
    get errorCount() {
      return errors.length
    },
    sources: () => sources,
    idAt: (index: number) => shown.at(index),
    indexOf: (id: number) => shown.indexOf(id),
    filter: () => filter,
    setFilter(store: LogStore, next: LogFilter) {
      filter = next
      needle = next.query.trim().toLowerCase()
      return rebuild(store)
    },
    sync(store: LogStore): LogIndexChange {
      const snapshot = store.getSnapshot()
      if (snapshot.generation !== generation) return rebuild(store)
      const removed = shown.dropBelow(snapshot.firstId)
      errors.dropBelow(snapshot.firstId)
      let added = 0
      for (let id = Math.max(synced + 1, snapshot.firstId); id <= snapshot.lastId; id++) {
        const line = store.get(id)
        if (line && take(line)) added++
      }
      synced = snapshot.lastId
      return { added, removed, rebuilt: false }
    },
    /** The shown error after (`1`) or before (`-1`) the shown line at `index`, as an index, or -1. */
    error(index: number, direction: 1 | -1) {
      const id = shown.at(index)
      if (errors.length === 0) return -1
      const from = id === undefined ? (direction === 1 ? 0 : errors.length) : errors.lowerBound(id)
      const target =
        direction === 1 ? errors.at(id !== undefined && errors.at(from) === id ? from + 1 : from) : errors.at(from - 1)
      return target === undefined ? -1 : shown.indexOf(target)
    },
    isError,
  }
}

type LogIndex = ReturnType<typeof createLogIndex>

export { createLogIndex }
export type { LogFilter, LogIndex, LogIndexChange }

import { createVirtualizer } from "@ui-sdk/core"

import { layersBesideViewport } from "@/components/ui/scroll-area-layers"

const AT_END_TOLERANCE_PX = 4

type LogScrollerOptions = {
  count: () => number
  key: (position: number) => string
  /** Positions that stay rendered wherever the log is scrolled, like the current error. */
  keep: () => readonly number[]
  following: () => boolean
  /** Called when the reader scrolls to or away from the end. */
  setFollowing: (following: boolean) => void
  onKeyDown: (event: KeyboardEvent) => void
}

/**
 * The log's scroller: UI SDK's virtualizer over the shown lines, the box that holds their height, and following the
 * end. Rows are one line high until lines wrap: the height comes from an element styled like a row, and only
 * wrapped rows are measured one by one.
 */
function createLogScroller(options: LogScrollerOptions) {
  let rowHeight = 20
  let scroller: HTMLElement | undefined
  let rows: HTMLElement | undefined
  let written = -1
  let scrollTopSetHere: number | undefined

  const virtual = createVirtualizer({
    count: options.count,
    estimate: () => rowHeight,
    key: options.key,
    overscan: 12,
    keep: options.keep,
  })

  const writeSize = () => {
    const size = virtual.size()
    if (!rows || size === written) return
    written = size
    rows.style.height = `${String(size)}px`
  }

  const setTop = (top: number) => {
    if (!scroller) return
    scroller.scrollTop = top
    scrollTopSetHere = scroller.scrollTop
  }

  const toEnd = () => {
    if (!scroller) return
    writeSize()
    const end = scroller.scrollHeight - scroller.clientHeight
    if (Math.abs(scroller.scrollTop - end) < 1) return
    setTop(end)
    virtual.refresh()
  }

  return {
    virtual,
    rowHeight: () => rowHeight,
    connected: () => scroller !== undefined,
    refresh(removedAbove = 0, averageRow = rowHeight) {
      virtual.refresh()
      writeSize()
      if (!scroller) return
      if (options.following()) toEnd()
      else if (removedAbove > 0) {
        const keepTextUnderReader = scroller.scrollTop - removedAbove * averageRow
        setTop(Math.max(0, keepTextUnderReader))
        virtual.refresh()
      }
    },
    resize() {
      virtual.reset()
      virtual.refresh()
      writeSize()
      if (options.following()) toEnd()
    },
    toEnd,
    // Workaround: Chrome's smooth keyboard scroll keeps moving after a later scroll to the end, so keys scroll
    // instantly here.
    scrollByKey(key: string) {
      if (!scroller) return false
      const page = Math.max(rowHeight, scroller.clientHeight - rowHeight)
      const deltas: Record<string, number> = {
        ArrowUp: -rowHeight,
        ArrowDown: rowHeight,
        PageUp: -page,
        PageDown: page,
      }
      const end = scroller.scrollHeight - scroller.clientHeight
      const top = key === "Home" ? 0 : scroller.scrollTop + (deltas[key] ?? Number.NaN)
      if (Number.isNaN(top)) return false
      setTop(Math.max(0, Math.min(end, top)))
      options.setFollowing(end - scroller.scrollTop <= AT_END_TOLERANCE_PX)
      virtual.refresh()
      return true
    },
    reveal(position: number) {
      virtual.scrollToIndex(position, { align: "center" })
      scrollTopSetHere = scroller?.scrollTop
    },
    inView() {
      if (!scroller) return { first: -1, last: options.count() }
      const top = scroller.scrollTop
      const bottom = top + scroller.clientHeight
      const shown = virtual.items().filter((item) => item.start + item.size > top && item.start < bottom)
      return { first: shown[0]?.index ?? -1, last: shown.at(-1)?.index ?? options.count() }
    },
    selectedText() {
      const selection = scroller?.ownerDocument.getSelection()
      if (!scroller || !selection || selection.isCollapsed) return undefined
      if (!scroller.contains(selection.anchorNode) || !scroller.contains(selection.focusNode)) return undefined
      return selection.toString()
    },
    connect(el: HTMLElement) {
      scroller = el
      const onScrollBeforeVirtualizer = () => {
        const top = el.scrollTop
        const scrolledHere = scrollTopSetHere !== undefined && Math.abs(top - scrollTopSetHere) < 2
        scrollTopSetHere = undefined
        if (!scrolledHere) options.setFollowing(el.scrollHeight - el.clientHeight - top <= AT_END_TOLERANCE_PX)
      }
      const followEndOnResize =
        typeof ResizeObserver === "function"
          ? new ResizeObserver(() => {
              if (options.following()) toEnd()
            })
          : undefined
      followEndOnResize?.observe(el)
      el.addEventListener("scroll", onScrollBeforeVirtualizer, { passive: true })
      el.addEventListener("keydown", options.onKeyDown)
      const restore = layersBesideViewport(el)
      const disconnect = virtual.connect(el)
      let size = virtual.size()
      const stopSize = virtual.subscribe(() => {
        if (virtual.size() === size) return
        size = virtual.size()
        writeSize()
        if (options.following()) toEnd()
      })
      return () => {
        el.removeEventListener("scroll", onScrollBeforeVirtualizer)
        el.removeEventListener("keydown", options.onKeyDown)
        followEndOnResize?.disconnect()
        stopSize()
        disconnect()
        restore()
        if (scroller === el) scroller = undefined
      }
    },
    bindRows(el: HTMLElement | null) {
      rows = el ?? undefined
      written = -1
      writeSize()
    },
    measureRow(el: HTMLElement | null) {
      if (!el || typeof ResizeObserver !== "function") return undefined
      const observer = new ResizeObserver(([entry]) => {
        const height = entry?.borderBoxSize?.[0]?.blockSize ?? el.getBoundingClientRect().height
        if (!height || Math.abs(height - rowHeight) < 0.01) return
        rowHeight = height
        virtual.reset()
        virtual.refresh()
        writeSize()
        if (options.following()) toEnd()
      })
      observer.observe(el)
      return () => observer.disconnect()
    },
  }
}

type LogScroller = ReturnType<typeof createLogScroller>

export { createLogScroller }
export type { LogScroller }

import { createChange, definePrimitive, dispatch, type ChangeDetails, type ChangeOptions } from "@ui-sdk/core"

import { settled, unavailable } from "@/lib/action-refusal"
import { createLogIndex, type LogIndexChange } from "@/components/ui/log-viewer-index"
import { createLogScroller } from "@/components/ui/log-viewer-scroller"
import { isErrorLevel, type LogLine, type LogStore } from "@/components/ui/log-viewer-store"

type LogViewerChangeReason = "toggle-press" | "input-change" | "imperative"

type LogViewerAnnouncements = {
  /** Read after new errors arrive, at most once per `announceDelay`. */
  newErrors: (errors: number) => string
  /** Read after new lines arrive, with `announce="lines"`. */
  newLines: (lines: number, errors: number) => string
}

type LogViewerOptions = {
  store?: LogStore
  /** Which lines are errors: a pattern their text matches, or a test. Lines with an `error` or `fatal` level always are. */
  isError?: RegExp | ((line: LogLine) => boolean)
  hiddenSources?: readonly string[]
  defaultHiddenSources?: readonly string[]
  onHiddenSourcesChange?: (hidden: string[], details: ChangeDetails<LogViewerChangeReason>) => void
  query?: string
  defaultQuery?: string
  onQueryChange?: (query: string, details: ChangeDetails<LogViewerChangeReason>) => void
  wrap?: boolean
  defaultWrap?: boolean
  onWrapChange?: (wrap: boolean, details: ChangeDetails<LogViewerChangeReason>) => void
  /** The sources the filter offers before they write, in order; others join as they appear. */
  sources?: readonly string[]
  /** How a line reads when copied, or read by agents. */
  format?: (line: LogLine) => string
  onCopy?: (text: string, details: ChangeDetails<"copy">) => void
  /** What screen readers hear as lines arrive: new errors (default), a count of new lines, or nothing. */
  announce?: "errors" | "lines" | "off"
  /** The least time between two announcements, in ms. @defaultValue 5000 */
  announceDelay?: number
  announcements?: Partial<LogViewerAnnouncements>
}

const defaultAnnouncements: LogViewerAnnouncements = {
  newErrors: (errors) => (errors === 1 ? "1 new error" : `${String(errors)} new errors`),
  newLines: (lines, errors) =>
    `${String(lines)} new ${lines === 1 ? "line" : "lines"}${errors > 0 ? `, ${String(errors)} ${errors === 1 ? "error" : "errors"}` : ""}`,
}

const COPIED_FOR = 2000

function formatLine(line: LogLine) {
  return line.source === undefined ? line.text : `[${line.source}] ${line.text}`
}

function errorTest(isError: LogViewerOptions["isError"]) {
  if (isError instanceof RegExp) {
    const pattern = new RegExp(isError.source, isError.flags.replace("g", "").replace("y", ""))
    return (line: LogLine) => isErrorLevel(line) || pattern.test(line.text)
  }
  if (typeof isError === "function") return (line: LogLine) => isErrorLevel(line) || isError(line)
  return isErrorLevel
}

function reasonOf(options: unknown): { reason: LogViewerChangeReason; event?: Event } {
  if (typeof options !== "object" || options === null) return { reason: "imperative" }
  const { reason = "imperative", event } = options as ChangeOptions<LogViewerChangeReason>
  return { reason, event: event instanceof Event ? event : undefined }
}

function sourceList(sources: unknown): string[] | undefined {
  if (sources === undefined || sources === null || sources === "") return undefined
  if (typeof sources === "string") return [sources]
  if (Array.isArray(sources) && sources.every((source) => typeof source === "string")) return sources as string[]
  throw new TypeError(`filter takes a source or a list of sources, not ${JSON.stringify(sources)}.`)
}

function focusLogAround(el: HTMLElement) {
  const log = el.closest('[data-slot="log-viewer"]')?.querySelector<HTMLElement>('[role="log"]')
  log?.focus({ preventScroll: true })
}

const sameList = (a: readonly string[], b: readonly string[]) =>
  a.length === b.length && a.every((value, index) => value === b[index])

type RootState = {
  count: number
  errors: number
  following: boolean
  newBelow: number
  wrap: boolean
  copied: boolean
  sources: string[]
  hiddenSources: string[]
  query: string
  announcement: string
  currentError: number | null
}

const logViewer = definePrimitive({
  name: "log-viewer",
  options: {
    store: "value",
    isError: "value",
    hiddenSources: "value",
    defaultHiddenSources: "value",
    onHiddenSourcesChange: "callback",
    query: "value",
    defaultQuery: "value",
    onQueryChange: "callback",
    wrap: "value",
    defaultWrap: "value",
    onWrapChange: "callback",
    sources: "value",
    format: "value",
    onCopy: "callback",
    announce: "string",
    announceDelay: "number",
    announcements: "value",
  },
  state: (options: LogViewerOptions): RootState => ({
    hiddenSources: [...(options.hiddenSources ?? options.defaultHiddenSources ?? [])],
    query: options.query ?? options.defaultQuery ?? "",
    wrap: options.wrap ?? options.defaultWrap ?? false,
    sources: [...(options.sources ?? [])],
    count: 0,
    errors: 0,
    following: true,
    newBelow: 0,
    currentError: null,
    copied: false,
    announcement: "",
  }),
  sync: (options) => ({
    ...(options.hiddenSources === undefined ? {} : { hiddenSources: [...options.hiddenSources] }),
    ...(options.query === undefined ? {} : { query: options.query }),
    ...(options.wrap === undefined ? {} : { wrap: options.wrap }),
  }),
  controlled: ["hiddenSources", "query", "wrap"],
  api: (context) => {
    const { store: state } = context
    const change = createChange(context)
    let index = createLogIndex(errorTest(context.options().isError))
    let copiedTimer: ReturnType<typeof setTimeout> | undefined
    let announceTimer: ReturnType<typeof setTimeout> | undefined
    let pending = { lines: 0, errors: 0 }

    const setFollowing = (following: boolean) => {
      if (state.get().following === following) return
      state.set(following ? { following, newBelow: 0 } : { following })
    }

    const scroller = createLogScroller({
      count: () => index.count,
      key: (position) => String(index.idAt(position)),
      keep: () => {
        const current = state.get().currentError
        const position = current === null ? -1 : index.indexOf(current)
        return position === -1 ? [] : [position]
      },
      following: () => state.get().following,
      setFollowing,
      onKeyDown: (event) => {
        if (event.defaultPrevented || event.altKey || event.ctrlKey || event.metaKey) return
        if (event.key === "End") {
          event.preventDefault()
          jumpToEnd()
        } else if (event.key === "F8") {
          event.preventDefault()
          goToError(event.shiftKey ? -1 : 1, event.shiftKey ? "previousError" : "nextError", event)
        } else if (!event.shiftKey && scroller.scrollByKey(event.key)) event.preventDefault()
      },
    })
    const { virtual } = scroller

    const logStore = () => context.options().store
    const knownSources = () => {
      const listed = context.options().sources ?? []
      const seen = index.sources().filter((source) => !listed.includes(source))
      return seen.length === 0 ? [...listed] : [...listed, ...seen]
    }

    const announce = () => {
      announceTimer = undefined
      const { lines, errors } = pending
      pending = { lines: 0, errors: 0 }
      const mode = context.options().announce ?? "errors"
      const texts = { ...defaultAnnouncements, ...context.options().announcements }
      const message =
        mode === "lines" && lines > 0 ? texts.newLines(lines, errors) : errors > 0 ? texts.newErrors(errors) : ""
      if (message) state.set({ announcement: message })
    }

    const queueAnnouncement = (lines: number, errors: number) => {
      const mode = context.options().announce ?? "errors"
      if (mode === "off") return
      pending = { lines: pending.lines + lines, errors: pending.errors + errors }
      if (announceTimer !== undefined || (pending.errors === 0 && mode !== "lines")) return
      announceTimer = setTimeout(announce, context.options().announceDelay ?? 5000)
    }

    const run = (update: () => LogIndexChange) => {
      const errorsBefore = index.errorCount
      const average = index.count > 0 ? virtual.size() / index.count : scroller.rowHeight()
      const { following, newBelow, currentError } = state.get()
      const indexChange = update()
      scroller.refresh(indexChange.rebuilt ? 0 : indexChange.removed, average)
      if (!indexChange.rebuilt) queueAnnouncement(indexChange.added, Math.max(0, index.errorCount - errorsBefore))
      const known = knownSources()
      state.set({
        count: index.count,
        errors: index.errorCount,
        newBelow: following || indexChange.rebuilt ? 0 : newBelow + indexChange.added,
        ...(sameList(known, state.get().sources) ? {} : { sources: known }),
        ...(currentError !== null && index.indexOf(currentError) === -1 ? { currentError: null } : {}),
      })
    }

    const sync = () => {
      const current = logStore()
      if (current) run(() => index.sync(current))
    }

    const refilter = () => {
      const current = logStore()
      if (!current) return
      const { hiddenSources, query } = state.get()
      run(() => index.setFilter(current, { hidden: new Set(hiddenSources), query }))
    }

    let subscribed = logStore()
    let unsubscribe = subscribed?.subscribe(sync)
    refilter()

    let { hiddenSources, query, wrap } = state.get()
    context.onDestroy(
      state.subscribe(() => {
        const next = state.get()
        if (next.wrap !== wrap) {
          wrap = next.wrap
          scroller.resize()
        }
        if (next.hiddenSources === hiddenSources && next.query === query) return
        hiddenSources = next.hiddenSources
        query = next.query
        refilter()
      }),
    )
    let isError = context.options().isError
    context.onOptions((options) => {
      const storeChanged = options.store !== subscribed
      const testChanged = options.isError !== isError
      if (!storeChanged && !testChanged) return
      if (storeChanged) {
        unsubscribe?.()
        subscribed = options.store
        unsubscribe = subscribed?.subscribe(sync)
      }
      if (testChanged) {
        isError = options.isError
        index = createLogIndex(errorTest(isError))
      }
      refilter()
    })
    context.onDestroy(() => {
      unsubscribe?.()
      clearTimeout(copiedTimer)
      clearTimeout(announceTimer)
    })

    function jumpToEnd() {
      state.set({ following: true, newBelow: 0, currentError: null })
      scroller.toEnd()
      return true
    }

    function goToError(direction: 1 | -1, action: string, event?: Event) {
      const call = { reason: event ? "press" : "imperative", event }
      if (index.errorCount === 0) return unavailable(action, "has no errors to go to", call)
      const current = state.get().currentError
      const currentIndex = current === null ? -1 : index.indexOf(current)
      const view = scroller.inView()
      const from = currentIndex !== -1 ? currentIndex : direction === 1 ? view.first - 1 : view.last + 1
      const target = index.error(from, direction)
      if (target === -1) {
        const why = direction === 1 ? "has no error after this one" : "has no error before this one"
        return unavailable(action, why, call)
      }
      setFollowing(false)
      state.set({ currentError: index.idAt(target) ?? null })
      scroller.reveal(target)
      return true
    }

    const shownLines = (read: (line: LogLine) => void) => {
      const current = logStore()
      current?.flush()
      for (let position = 0; position < index.count; position++) {
        const line = current?.get(index.idAt(position)!)
        if (line) read(line)
      }
    }

    const setHiddenSources = (hidden: readonly string[], options?: ChangeOptions<LogViewerChangeReason>) => {
      const call = reasonOf(options)
      const next = [...hidden]
      if (sameList(next, state.get().hiddenSources)) return true
      return settled(change("hiddenSources", next, call), "filter", call)
    }

    const text = () => {
      const format = context.options().format ?? formatLine
      const lines: string[] = []
      shownLines((line) => lines.push(format(line)))
      return lines.join("\n")
    }

    return {
      virtual,
      /** Every source the filter offers, as one array that changes only when a source joins. */
      sources: () => state.get().sources,
      /** Calls `listener` on every state change; read `sources()` to see whether they changed. */
      subscribe: (listener: () => void) => state.subscribe(listener),
      /** The line with this id, while the store keeps it. */
      line: (id: number) => logStore()?.get(id),
      isError: (line: LogLine) => index.isError(line),
      /** Follows the scroller, from the log part's element. */
      connect(el: HTMLElement) {
        const disconnect = scroller.connect(el)
        sync()
        if (state.get().following) scroller.toEnd()
        return disconnect
      },
      bindRows: scroller.bindRows,
      measureRow: scroller.measureRow,
      /** Measures a rendered row while lines wrap, when their heights differ. */
      measure: (position: number, el: HTMLElement | null) => virtual.measure(position, el),
      /** Scrolls to the newest line and follows new ones again. */
      jumpToEnd,
      /** Shows only these sources, by name; nothing, or an empty list, shows every source. */
      filter(sources?: unknown, options?: ChangeOptions<LogViewerChangeReason>) {
        const shown = sourceList(sources)
        const known = state.get().sources
        const unknown = shown?.filter((source) => !known.includes(source)) ?? []
        if (unknown.length > 0) {
          const names = unknown.map((source) => JSON.stringify(source)).join(", ")
          throw new RangeError(`No source ${names}. Sources: ${known.join(", ") || "none yet"}.`)
        }
        const hidden =
          shown === undefined || shown.length === 0 ? [] : known.filter((source) => !shown.includes(source))
        return setHiddenSources(hidden, options)
      },
      setHiddenSources,
      /** Shows only the lines that contain this text, in any case; an empty one shows every line. */
      search(needle?: unknown, options?: ChangeOptions<LogViewerChangeReason>) {
        const call = reasonOf(options)
        const next = needle === undefined || needle === null ? "" : String(needle)
        if (next === state.get().query) return true
        return settled(change("query", next, call), "search", call)
      },
      setWrap(next: unknown, options?: ChangeOptions<LogViewerChangeReason>) {
        const call = reasonOf(options)
        const value = next === true || next === "true"
        if (value === state.get().wrap) return true
        return settled(change("wrap", value, call), "setWrap", call)
      },
      nextError: (event?: Event) => goToError(1, "nextError", event),
      previousError: (event?: Event) => goToError(-1, "previousError", event),
      /**
       * Writes the selected text to the clipboard, or every shown line (what the filter and search leave) as
       * plain text, one per line. Where the page has no clipboard access, a press gets false.
       */
      copy(event?: Event) {
        const clipboard = typeof navigator === "undefined" ? undefined : navigator.clipboard
        if (!clipboard) return unavailable("copy", "isn't available: the page has no clipboard access", { event })
        const copied = scroller.selectedText() ?? text()
        return clipboard.writeText(copied).then(
          () => {
            clearTimeout(copiedTimer)
            state.set({ copied: true })
            copiedTimer = setTimeout(() => state.set({ copied: false }), COPIED_FOR)
            dispatch(context, "onCopy", copied, { reason: "copy", event })
            return true
          },
          () => unavailable("copy", "was blocked by the browser", { event }),
        )
      },
      /** Every shown line, as `format` writes it, one per line. */
      text,
      /** The shown lines as agents read them: `value` is the line's id, `label` its text. */
      items() {
        const format = context.options().format ?? formatLine
        const items: { value: string; label: string }[] = []
        shownLines((line) => items.push({ value: String(line.id), label: format(line) }))
        return items
      },
    }
  },
  slots: (slot) => ({
    root: slot<{}, RootState>({
      role: "group",
      state: (state) => ({ ...state }),
      attrs: (state) => ({
        "data-following": state.following ? "" : undefined,
        "data-wrap": state.wrap ? "" : undefined,
        "data-copied": state.copied ? "" : undefined,
      }),
    }),
    // Spec: a log is a live region that would read rows coming and going on scroll; the status part announces instead.
    log: slot({
      role: "log",
      attrs: () => ({ tabindex: "0", "aria-live": "off" }),
      bind: (el, { api }) => api.connect(el),
    }),
    jump: slot<{}, { newBelow: number }>({
      role: "button",
      focus: "native",
      present: (state) => !state.following,
      state: (state) => ({ newBelow: state.newBelow }),
      attrs: (state) => ({ type: "button", "data-count": String(state.newBelow) }),
      press: ({ api, el }) => {
        const hadFocus = el !== undefined && el.ownerDocument.activeElement === el
        api.jumpToEnd()
        if (hadFocus) focusLogAround(el)
      },
    }),
    status: slot({
      role: "status",
      attrs: () => ({ "aria-live": "polite", "aria-atomic": "true" }),
    }),
  }),
  agent: {
    actions: ["filter", "search", "jumpToEnd", "nextError", "previousError", "copy", "setWrap"],
    items: (api) => api.items(),
  },
})

